<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../helpers/auth.php';
class LaporanController{public function index(){require_role(['admin','petugas']);$db=Database::getConnection();$status=$_GET['status']??'';$from=$_GET['from']??'';$to=$_GET['to']??'';$sql='SELECT p.kode_peminjaman,u.nama nama_peminjam,p.tanggal_pinjam,p.tanggal_kembali_rencana,p.tanggal_kembali_actual,p.status,COALESCE(SUM(d.jumlah),0) total_item FROM peminjaman p JOIN users u ON u.id=p.user_id LEFT JOIN detail_peminjaman d ON d.peminjaman_id=p.id WHERE 1=1';$args=[];if($status){$sql.=' AND p.status=?';$args[]=$status;}if($from){$sql.=' AND p.tanggal_pinjam>=?';$args[]=$from;}if($to){$sql.=' AND p.tanggal_pinjam<=?';$args[]=$to;} $sql.=' GROUP BY p.id ORDER BY p.id DESC LIMIT 200';$s=$db->prepare($sql);$s->execute($args);$rows=$s->fetchAll();require __DIR__.'/../views/laporan/index.php';}}
